static const AppIconImage kAppIconImages[] = {
    {16, kAppIcon16},
    {32, kAppIcon32},
    {48, kAppIcon48},
    {64, kAppIcon64},
};

inline const AppIconImage *app_icon_images(size_t *count) {
    if (count) *count = sizeof(kAppIconImages) / sizeof(kAppIconImages[0]);
    return kAppIconImages;
}

